const { test, expect } = await import(process.env.BW_PLAYWRIGHT_TEST);

test("AC-021 the output's text, given no expected value", async ({ page }) => {
  await page.goto("index.html");
  await expect(page.locator("#out")).toHaveText(undefined);
});

